/**
 * DEEP-BUG-035: never publish a 0 kg BRSR headline when category/scope rows have mass.
 * Prefer the API total when positive; otherwise fall back to scopes, categories, hotspots, then footprint.
 */

type GhgBlock = {
  total?: number | null;
  scope1?: number | null;
  scope2?: number | null;
  scope3?: number | null;
} | null | undefined;

type CategoryRow = { value?: number | null } | null | undefined;
type HotspotRow = { emissionsKgCO2e?: number | null } | null | undefined;

const asPositive = (value: unknown): number => {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : 0;
};

const sumRows = (
  rows: Array<CategoryRow | HotspotRow> | null | undefined,
  pick: (row: NonNullable<CategoryRow | HotspotRow>) => unknown
): number => {
  if (!Array.isArray(rows) || rows.length === 0) {
    return 0;
  }
  return rows.reduce((sum, row) => sum + (row ? asPositive(pick(row)) : 0), 0);
};

export function resolveBrsrPublishedTotalKg(input: {
  greenhouseGasEmissions?: GhgBlock;
  categoryBreakdown?: CategoryRow[] | null;
  hotspots?: HotspotRow[] | null;
  footprintTotalKg?: number | null;
}): number {
  const ghg = input.greenhouseGasEmissions;
  const header = asPositive(ghg?.total);
  if (header > 0) {
    return header;
  }

  const scopeSum =
    asPositive(ghg?.scope1) + asPositive(ghg?.scope2) + asPositive(ghg?.scope3);
  if (scopeSum > 0) {
    return scopeSum;
  }

  const categorySum = sumRows(input.categoryBreakdown, (row) => (row as { value?: number }).value);
  if (categorySum > 0) {
    return categorySum;
  }

  const hotspotSum = sumRows(
    input.hotspots,
    (row) => (row as { emissionsKgCO2e?: number }).emissionsKgCO2e
  );
  if (hotspotSum > 0) {
    return hotspotSum;
  }

  return asPositive(input.footprintTotalKg);
}
