import React, { useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Collapse,
  IconButton,
  Stack,
  Typography,
} from '@mui/material';
import {
  AutoFixHigh as AutopilotIcon,
  ExpandLess as ExpandLessIcon,
  ExpandMore as ExpandMoreIcon,
  PlayArrow as PlayArrowIcon,
  TrendingDown as TrendingDownIcon,
  TrendingFlat as TrendingFlatIcon,
  TrendingUp as TrendingUpIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import OrchestrationRunPanel, { OrchestrationRunSummary } from '../compliance/OrchestrationRunPanel';
import {
  FRAMEWORK_ACRONYM_HINTS,
  READINESS_ACTION_LABELS,
  READINESS_CHECK_PRIMARY_LABEL,
} from '../../constants/orchestrationUxLabels';
import useReadinessLocale from '../../hooks/useReadinessLocale';
import { msmeProgressLabel } from '../../constants/reportingUxLabels';

export type FrameworkReadinessDelta = {
  framework: string;
  scoreBefore?: number | null;
  scoreAfter?: number | null;
  scoreDelta?: number | null;
  improved?: boolean;
  regressed?: boolean;
};

export type TrackReadinessDelta = {
  track: string;
  label: string;
  scoreBefore?: number | null;
  scoreAfter?: number | null;
  scoreDelta?: number | null;
};

export type ReadinessOrchestrationInsight = {
  hasHistory?: boolean;
  lastRunAt?: string | null;
  lastRunAgeLabel?: string | null;
  lastOrchestratorType?: string;
  overallDelta?: number | null;
  overallScoreBefore?: number | null;
  overallScoreAfter?: number | null;
  trackDeltas?: TrackReadinessDelta[];
  frameworkDeltas?: FrameworkReadinessDelta[];
  improvedFrameworks?: FrameworkReadinessDelta[];
  regressedFrameworks?: FrameworkReadinessDelta[];
  closuresAppliedCount?: number;
  documentsVerifiedCount?: number;
  scope3ReclassificationsCount?: number;
  cbamInstallationDerived?: boolean;
  headline?: string | null;
  stages?: Array<{ stage: string; status: string }>;
  stagesCompleted?: number;
  stagesFailed?: number;
  openGapsRemaining?: number | null;
};

type ReportingOrchestrationDeltaBannerProps = {
  insight?: ReadinessOrchestrationInsight | null;
  overallReadinessScore?: number | null;
  indiaOverallReadinessScore?: number | null;
  exportOverallReadinessScore?: number | null;
  exportApplicable?: boolean;
  period?: string;
  isMsmeSimplified?: boolean;
  reportingExpertMode?: boolean;
  running?: boolean;
  onRunReadinessCheck?: () => void;
  lastOrchestrationRun?: OrchestrationRunSummary | null;
  hidePrimaryActions?: boolean;
  hideEmptyPrompt?: boolean;
};

const deltaColor = (delta?: number | null): 'success' | 'warning' | 'default' => {
  if (delta == null || delta === 0) return 'default';
  return delta > 0 ? 'success' : 'warning';
};

const normalizeDeltaPercent = (delta?: number | null): number | null => {
  if (delta == null || delta === 0) return delta ?? null;
  const numeric = Number(delta);
  if (!Number.isFinite(numeric)) return null;
  return Math.abs(numeric) <= 1 ? numeric * 100 : numeric;
};

const scoreBandBorderColor = (score?: number | null): string => {
  if (score == null) return 'divider';
  if (score >= 75) return 'success.light';
  if (score >= 50) return 'warning.light';
  return 'error.light';
};

const DeltaChip: React.FC<{ delta?: number | null; prefix?: string }> = ({ delta, prefix = '' }) => {
  const normalizedDelta = normalizeDeltaPercent(delta);
  if (normalizedDelta == null || normalizedDelta === 0) {
    return (
      <Chip
        size="small"
        icon={<TrendingFlatIcon />}
        label={`${prefix}No change`}
        variant="outlined"
      />
    );
  }
  const sign = normalizedDelta > 0 ? '+' : '';
  return (
    <Chip
      size="small"
      icon={normalizedDelta > 0 ? <TrendingUpIcon /> : <TrendingDownIcon />}
      label={`${prefix}${sign}${Math.round(normalizedDelta * 10) / 10}%`}
      color={deltaColor(normalizedDelta)}
      variant="outlined"
    />
  );
};

export const getFrameworkDelta = (
  insight: ReadinessOrchestrationInsight | null | undefined,
  framework: string
): FrameworkReadinessDelta | null => {
  const key = framework.toUpperCase();
  return (insight?.frameworkDeltas || []).find((entry) => entry.framework === key) || null;
};

const ReportingOrchestrationDeltaBanner: React.FC<ReportingOrchestrationDeltaBannerProps> = ({
  insight,
  overallReadinessScore,
  indiaOverallReadinessScore,
  exportOverallReadinessScore,
  exportApplicable = false,
  period: _period = 'annual',
  isMsmeSimplified = false,
  reportingExpertMode = false,
  running = false,
  onRunReadinessCheck,
  lastOrchestrationRun = null,
  hidePrimaryActions = false,
  hideEmptyPrompt = false,
}) => {
  const { strings } = useReadinessLocale();
  const [expanded, setExpanded] = useState(false);

  const displayScore = overallReadinessScore ?? insight?.overallScoreAfter ?? null;
  const headline = insight?.headline
    || (displayScore != null
      ? (isMsmeSimplified && !reportingExpertMode
        ? msmeProgressLabel(displayScore)
        : `Current readiness ${Math.round(displayScore)}%`)
      : 'Run a readiness check to see your filing scores');

  const improvementSummary = useMemo(() => {
    const parts: string[] = [];
    if ((insight?.closuresAppliedCount || 0) > 0) {
      parts.push(`${insight?.closuresAppliedCount} improvement${insight?.closuresAppliedCount === 1 ? '' : 's'} applied`);
    }
    if ((insight?.documentsVerifiedCount || 0) > 0) {
      parts.push(`${insight?.documentsVerifiedCount} bill${insight?.documentsVerifiedCount === 1 ? '' : 's'} verified`);
    }
    if ((insight?.scope3ReclassificationsCount || 0) > 0) {
      parts.push(`${insight?.scope3ReclassificationsCount} Scope 3 update${insight?.scope3ReclassificationsCount === 1 ? '' : 's'}`);
    }
    if (insight?.cbamInstallationDerived) {
      parts.push('CBAM Tier-1 emissions derived');
    }
    return parts;
  }, [insight]);

  const notableFrameworkDeltas = (insight?.frameworkDeltas || [])
    .filter((entry) => entry.scoreDelta != null && entry.scoreDelta !== 0)
    .slice(0, 6);

  if (running) {
    return (
      <Card variant="outlined" sx={{ borderColor: 'primary.light', bgcolor: 'action.hover' }}>
        <CardContent>
          <OrchestrationRunPanel running runningStageLabel={READINESS_CHECK_PRIMARY_LABEL} />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card
      variant="outlined"
      sx={{
        borderColor: scoreBandBorderColor(displayScore),
        bgcolor: 'background.paper',
      }}
    >
      <CardContent>
        <Stack
          direction={{ xs: 'column', md: 'row' }}
          spacing={2}
          alignItems={{ xs: 'stretch', md: 'flex-start' }}
          justifyContent="space-between"
        >
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography variant="overline" color="text.secondary">
              Reporting readiness
              {insight?.lastRunAgeLabel ? ` · Updated ${insight.lastRunAgeLabel}` : ''}
            </Typography>
            <Stack direction="row" spacing={1.5} alignItems="baseline" flexWrap="wrap" useFlexGap sx={{ mt: 0.5 }}>
              {displayScore != null ? (
                <Typography variant="h3" component="span" color="primary.main" fontWeight={700}>
                  {Math.round(displayScore)}%
                </Typography>
              ) : null}
              <DeltaChip delta={insight?.overallDelta} />
            </Stack>
            <Typography variant="body1" sx={{ mt: 1, fontWeight: 600 }}>
              {headline}
            </Typography>
            {isMsmeSimplified && !reportingExpertMode ? (
              <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                {strings.hubHandoff}
              </Typography>
            ) : null}
            <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mt: 1.5 }}>
              {indiaOverallReadinessScore != null && (!isMsmeSimplified || reportingExpertMode) ? (
                <Chip
                  size="small"
                  label={`India ${Math.round(indiaOverallReadinessScore)}%`}
                  variant="outlined"
                />
              ) : null}
              {exportApplicable && exportOverallReadinessScore != null
                && (!isMsmeSimplified || reportingExpertMode) ? (
                  <Chip
                    size="small"
                    label={`Export ${Math.round(exportOverallReadinessScore)}%`}
                    variant="outlined"
                  />
                ) : null}
              {(insight?.trackDeltas || []).map((track) => (
                <DeltaChip key={track.track} delta={track.scoreDelta} prefix={`${track.label} `} />
              ))}
            </Stack>
            {improvementSummary.length > 0 ? (
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                {improvementSummary.join(' · ')}
              </Typography>
            ) : null}
          </Box>

          <Stack spacing={1} sx={{ minWidth: { md: 220 }, display: hidePrimaryActions || (isMsmeSimplified && !reportingExpertMode) ? 'none' : undefined }}>
            {onRunReadinessCheck ? (
              <Button
                variant="contained"
                startIcon={<PlayArrowIcon />}
                onClick={onRunReadinessCheck}
                fullWidth
              >
                {READINESS_CHECK_PRIMARY_LABEL}
              </Button>
            ) : null}
            <Button
              variant="outlined"
              startIcon={<AutopilotIcon />}
              component={RouterLink}
              to="/compliance"
              fullWidth
            >
              {READINESS_ACTION_LABELS.autoFixFromDocuments}
            </Button>
            <Button
              variant="text"
              component={RouterLink}
              to="/compliance"
              fullWidth
            >
              Open Compliance Hub
            </Button>
          </Stack>
        </Stack>

        {notableFrameworkDeltas.length > 0 && (!isMsmeSimplified || reportingExpertMode) ? (
          <Box sx={{ mt: 2 }}>
            <Typography variant="caption" color="text.secondary" fontWeight={600} display="block" sx={{ mb: 0.75 }}>
              Framework changes since last check
            </Typography>
            <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
              {notableFrameworkDeltas.map((entry) => (
                <Chip
                  key={entry.framework}
                  size="small"
                  label={`${entry.framework} ${entry.scoreDelta && entry.scoreDelta > 0 ? '+' : ''}${entry.scoreDelta}%`}
                  color={deltaColor(entry.scoreDelta)}
                  variant="outlined"
                  title={FRAMEWORK_ACRONYM_HINTS[entry.framework] || entry.framework}
                />
              ))}
            </Stack>
          </Box>
        ) : null}

        {(lastOrchestrationRun || (insight?.stages || []).length > 0)
          && (!isMsmeSimplified || reportingExpertMode) ? (
          <Box sx={{ mt: 1 }}>
            <Stack direction="row" alignItems="center" justifyContent="space-between">
              <Typography variant="caption" color="text.secondary" fontWeight={600}>
                Last readiness check details
              </Typography>
              <IconButton
                size="small"
                aria-label={expanded ? 'Hide readiness check details' : 'Show readiness check details'}
                onClick={() => setExpanded((value) => !value)}
              >
                {expanded ? <ExpandLessIcon /> : <ExpandMoreIcon />}
              </IconButton>
            </Stack>
            <Collapse in={expanded}>
              <Box sx={{ mt: 1 }}>
                <OrchestrationRunPanel
                  lastRun={lastOrchestrationRun}
                  stages={insight?.stages}
                  compact
                />
                {insight?.openGapsRemaining != null ? (
                  <Alert severity="info" sx={{ mt: 1 }}>
                    {insight.openGapsRemaining} open gap{insight.openGapsRemaining === 1 ? '' : 's'} remaining after the last check.
                  </Alert>
                ) : null}
              </Box>
            </Collapse>
          </Box>
        ) : null}

        {!hideEmptyPrompt && !insight?.hasHistory ? (
          <Alert severity="info" sx={{ mt: 2 }}>
            <Typography variant="body2">
              Run a full readiness check to apply ISO, BRSR, PCF, and CBAM improvements from your bills and see score changes here.
            </Typography>
          </Alert>
        ) : null}
      </CardContent>
    </Card>
  );
};

export default ReportingOrchestrationDeltaBanner;
